<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {useAuth} from '../stores/auth';
import {realApi} from '../api/real';
import {managementRequest,cycleStage} from '../api/management';
type Row={user_id:string;display_name:string;department_name:string|null;peer_expected:number;peer_submitted:number;self_submitted:boolean;build_id:string|null;build_status:string|null;exact_score:number|string|null;build_at:string|null;dimension_json:any;publication_id:string|null;publication_version:number|null;published_at:string|null;incomplete_reasons:string[]};
const auth=useAuth(),route=useRoute(),cycles=ref<any[]>([]),cycleId=ref(''),rows=ref<Row[]>([]),history=ref<any[]>([]),tab=ref('people'),search=ref(''),department=ref(''),state=ref(''),page=ref(1),selected=ref<Row|null>(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');let request=0;
const rawScores=ref<any[]>([]),rawError=ref('');
async function show(row:Row){selected.value=row;rawScores.value=[];rawError.value='';if(!auth.hasCapability('calibration.read_raw'))return;const id=cycleId.value;try{const records=await realApi.listReviewScores(id);if(cycleId.value===id&&selected.value?.user_id===row.user_id)rawScores.value=records.filter((r:any)=>r.targetId===row.user_id);}catch(e){rawError.value=e instanceof Error?e.message:'原始评分加载失败';}}
const current=computed(()=>cycles.value.find(c=>c.id===cycleId.value));
const count=computed(()=>rows.value.length),complete=computed(()=>rows.value.filter(r=>!r.incomplete_reasons.length).length),built=computed(()=>rows.value.filter(r=>r.build_id&&r.build_status!=='STALE').length),pending=computed(()=>rows.value.filter(r=>r.build_status==='BUILT').length),published=computed(()=>rows.value.filter(r=>r.publication_id).length);
const status=(r:Row)=>r.build_status==='STALE'?'需重新核算':r.build_status==='PUBLISHED'?'已发布':r.build_status==='APPROVED'?'已确认':r.build_status==='BUILT'?'待确认':'待核算';
const departments=computed(()=>[...new Set(rows.value.map(r=>r.department_name).filter((d):d is string=>!!d))]);
const filtered=computed(()=>rows.value.filter(r=>(tab.value!=='pending'||r.build_status==='BUILT')&&(!search.value||r.display_name.includes(search.value.trim()))&&(!department.value||department.value===r.department_name)&&(!state.value||state.value===status(r))));
const totalPages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))),visible=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));
watch([tab,search,department,state,cycleId],()=>{page.value=1;});
async function load(){const id=cycleId.value,token=++request;rows.value=[];history.value=[];error.value='';notice.value='';selected.value=null;if(!id)return;loading.value=true;try{const data=await managementRequest<Row[]>(`management/result-overview?cycleId=${encodeURIComponent(id)}`);if(token===request)rows.value=data;}catch(e){if(token===request)error.value=e instanceof Error?e.message:'加载失败';}finally{if(token===request)loading.value=false;}}
async function loadHistory(){if(!cycleId.value)return;const id=cycleId.value;try{const data=await managementRequest<any[]>(`management/archives?cycleId=${encodeURIComponent(id)}&history=true`);if(id===cycleId.value)history.value=data;}catch(e){error.value=e instanceof Error?e.message:'发布记录加载失败';}}
watch(tab,v=>{if(v==='history')void loadHistory();});watch(cycleId,()=>void load());
onMounted(async()=>{try{cycles.value=await realApi.listCycles();cycleId.value=(cycles.value.find(c=>c.id===route.query.cycleId)??cycles.value.find(c=>c.status==='CALIBRATING')??cycles.value[0])?.id??'';}catch(e){error.value=e instanceof Error?e.message:'周期加载失败';}});
async function build(){if(!cycleId.value||busy.value||!window.confirm('将为当前周期符合条件的参评人员构建结果，继续吗？'))return;busy.value=true;error.value='';try{const result=await realApi.buildResults(cycleId.value);await load();notice.value=`本次构建 ${result.items.length} 份，${result.incomplete?.length??0} 人未满足构建条件。`;}catch(e){error.value=e instanceof Error?e.message:'构建失败';}finally{busy.value=false;}}
async function act(row:Row,kind:'confirm'|'publish'){if(!row.build_id||busy.value||!window.confirm(`确认${kind==='confirm'?'确认':'发布'} ${row.display_name} 的结果？`))return;busy.value=true;error.value='';try{if(kind==='confirm')await realApi.approveBuild(row.build_id);else await realApi.publishBuild(row.build_id);await load();notice.value=`${row.display_name} 的操作已完成。`;}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
const pct=(n:number)=>count.value?Math.round(n/count.value*100):null;
const metrics=computed(()=>[{label:'数据完整性',n:complete.value},{label:'核算完成',n:built.value},{label:'待确认',n:pending.value},{label:'已发布',n:published.value}]);
</script>
<template><div class="results-page"><div class="intro"><div><h2>结果管理</h2><p>检查评价数据，构建结果并由授权人员确认、发布。</p></div><label>当前周期 <select v-model="cycleId"><option v-for="c in cycles" :key="c.id" :value="c.id">{{c.title}}（{{c.month}}）</option></select></label></div><p class="hint">统计仅包含您有权查看的有效参评成员，不包含本人结果。</p><div v-if="error" class="error" role="alert">{{error}} <button @click="load">重试</button></div><p v-if="notice" role="status">{{notice}}</p><section class="overview"><div><small>当前周期</small><h2>{{current?.title??'暂无周期'}}</h2><span>{{current?cycleStage(current.status):'—'}}</span></div><div><small>结果检查</small><strong>{{complete}} / {{count}}</strong></div><div><small>结果构建与确认</small><strong>{{built}} / {{count}}</strong></div><div><small>正式发布</small><strong>{{published}} / {{count}}</strong></div></section><div class="top"><section class="panel"><h3>结果处理进度</h3><div class="metrics"><div v-for="m in metrics" :key="m.label"><span>{{m.label}}</span><strong>{{m.n}} / {{count}}</strong><progress v-if="count" :value="m.n" :max="count"/><small>{{pct(m.n)===null?'—':pct(m.n)+'%'}}</small></div></div></section><section class="panel operations"><h3>操作入口</h3><button @click="tab='pending'">查看待确认结果 →</button><button :disabled="busy||!auth.hasCapability('calibration.resolve')||!cycleId" @click="build">构建 / 刷新结果 →</button><p class="hint">确认和发布请在对应成员的详情中逐条操作。</p></section></div><section class="panel"><div class="tabs"><button :class="{active:tab==='people'}" @click="tab='people'">个人结果</button><button :class="{active:tab==='pending'}" @click="tab='pending'">待确认列表（{{pending}}）</button><button :class="{active:tab==='history'}" @click="tab='history'">发布记录</button></div><template v-if="tab!=='history'"><div class="filters"><input v-model="search" placeholder="搜索成员姓名"><select v-model="department"><option value="">全部部门</option><option v-for="d in departments" :key="d">{{d}}</option></select><select v-model="state"><option value="">全部状态</option><option>待核算</option><option>待确认</option><option>已确认</option><option>已发布</option><option>需重新核算</option></select></div><div class="scroll"><table><thead><tr><th>姓名</th><th>部门</th><th>有效他评数量</th><th>自评状态</th><th>最终分数</th><th>结果状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in visible" :key="r.user_id"><td>{{r.display_name}}</td><td>{{r.department_name??'—'}}</td><td>{{r.peer_submitted}} / {{r.peer_expected}}</td><td>{{r.self_submitted?'已完成':'未完成'}}</td><td>{{r.build_status&&r.build_status!=='STALE'&&r.exact_score!=null?Number(r.exact_score).toFixed(4):'—'}}</td><td><span class="badge">{{status(r)}}</span></td><td><button @click="show(r)">查看</button></td></tr></tbody></table></div><p v-if="loading">加载中…</p><p v-else-if="!filtered.length">暂无符合条件的成员结果。</p><div class="pagination">共 {{filtered.length}} 条 <button :disabled="page<=1" @click="page--">上一页</button>{{page}} / {{totalPages}} <button :disabled="page>=totalPages" @click="page++">下一页</button></div></template><template v-else><p class="hint">按个人发布版本展示；历史快照不会覆盖。</p><div class="scroll"><table><thead><tr><th>成员</th><th>历史部门</th><th>发布版本</th><th>发布时间</th></tr></thead><tbody><tr v-for="r in history" :key="r.id"><td>{{r.display_name}}</td><td>{{r.department_name??'—'}}</td><td>v{{r.publication_version}}</td><td>{{r.published_at?new Date(r.published_at).toLocaleString():'—'}}</td></tr></tbody></table></div><p v-if="!history.length">暂无可查看的发布记录，或当前账号无已发布结果查看权限。</p></template></section><div v-if="selected" class="overlay" @click.self="selected=null"><section class="dialog" role="dialog" aria-modal="true"><h2>{{selected.display_name}} · 结果详情</h2><p>部门：{{selected.department_name??'—'}}　状态：{{status(selected)}}</p><p>有效他评：{{selected.peer_submitted}} / {{selected.peer_expected}}　自评：{{selected.self_submitted?'已完成':'未完成'}}</p><p>最终成绩：{{selected.build_status&&selected.build_status!=='STALE'&&selected.exact_score!=null?Number(selected.exact_score).toFixed(4):'—'}}</p><p>构建时间：{{selected.build_at?new Date(selected.build_at).toLocaleString():'—'}}</p><p>发布版本：{{selected.publication_version??'未发布'}}　{{selected.published_at?new Date(selected.published_at).toLocaleString():''}}</p><div v-if="auth.hasCapability('calibration.read_raw')"><strong>有效他评记录</strong><p v-for="score in rawScores" :key="score.reviewId">{{score.reviewerName}}：{{score.score ?? '—'}} 分 · v{{score.revisionNo}}</p><p v-if="rawError" class="error">{{rawError}}</p><p v-else-if="!rawScores.length">暂无可查看的有效他评。</p></div><p v-else class="hint">原始他评记录需单独授权。</p><div v-if="selected.incomplete_reasons.length"><strong>尚未满足构建条件</strong><p v-for="r in selected.incomplete_reasons" :key="r">{{r}}</p></div><div class="actions"><button v-if="selected.build_status==='BUILT'&&auth.hasCapability('result.confirm')" :disabled="busy" @click="act(selected,'confirm')">确认结果</button><button v-if="selected.build_status==='APPROVED'&&auth.hasCapability('result.publish')" :disabled="busy" @click="act(selected,'publish')">发布结果</button><button @click="selected=null">关闭</button></div><p v-if="error" class="error">{{error}}</p></section></div></div></template>
<style scoped>
.intro,.filters,.pagination,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.intro h2{margin:0}.intro p,.hint,small{color:#718099}.overview,.panel,.dialog{background:#fff;border:1px solid #e1e8f2;border-radius:12px;padding:20px}.overview{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:18px;margin:18px 0}.overview strong,.metrics strong{display:block;font-size:20px;margin:8px 0}.overview h2{font-size:20px}.top{display:grid;grid-template-columns:3fr 1fr;gap:14px;margin-bottom:16px}.panel h3{margin:0 0 16px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metrics>div{border:1px solid #edf1f7;border-radius:8px;padding:14px}.metrics span{font-size:13px}.metrics progress{width:100%;accent-color:#3370ff}.operations button{display:block;text-align:left;padding:10px 0;width:100%}.tabs{display:flex;gap:24px;border-bottom:1px solid #edf1f7}.tabs button{padding:10px 2px}.tabs .active{border-bottom:2px solid #246bfd}.filters{justify-content:flex-start;margin:16px 0}.filters input,select{border:1px solid #dce4ef;border-radius:6px;padding:8px;background:white}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:13px;text-align:left;border-bottom:1px solid #edf1f7;white-space:nowrap}th{background:#f4f7fc;color:#687890}button{border:0;background:transparent;color:#246bfd;cursor:pointer}button:disabled{color:#aab3bf;cursor:not-allowed}.badge{color:#246bfd;background:#edf3ff;padding:4px 7px;border-radius:4px}.pagination{justify-content:flex-end;margin-top:15px}.error{color:#b42318}.overlay{position:fixed;inset:0;z-index:1000;background:#0006;display:grid;place-items:center}.dialog{width:min(560px,90vw);max-height:85vh;overflow:auto}.actions{justify-content:flex-end}@media(max-width:1100px){.overview,.metrics{grid-template-columns:repeat(2,1fr)}.top{grid-template-columns:1fr}}
</style>

